(function executeRule(current, previous /*null when async*/ ) {

    var gr = new GlideRecord('ais_search_profile_ais_search_source_m2m');
    gr.addQuery('profile', current.profile);
    gr.addQuery('search_source', current.search_source);
    gr.query();
    if (gr.next()) {
        gs.addErrorMessage(gs.getMessage('The selected search source was not added because it is already linked to this search profile.'));
        current.setAbortAction(true);
    }

})(current, previous);

(function executeRule(current, previous /*null when async*/) {

		if(previous.sheet_number==0 && previous.sheet_name==0){
		if(current.sheet_number==0){
			current.sheet_number = current.sheet_name;
		}else{
			current.sheet_name = current.sheet_number;
		}
	}else{
		if(previous.sheet_name!=current.sheet_name){
			current.sheet_number = current.sheet_name;
		}else if(previous.sheet_number!=current.sheet_number){
			current.sheet_name = current.sheet_number;
		}
	}

})(current, previous);
